add_action( 'admin_menu', 'perfectpixel_resend_completed_menu', 61 );

function perfectpixel_resend_completed_menu() {
	add_submenu_page( 'woocommerce', 'Επαναποστολή emails', 'Επαναποστολή emails', 'manage_woocommerce', 'perfectpixel-resend-completed', 'perfectpixel_resend_completed_page' );
}

function perfectpixel_resend_completed_page() {
	if ( ! current_user_can( 'manage_woocommerce' ) ) {
		return;
	}
	echo '<div class="wrap"><h1>Επαναποστολή emails «Ολοκληρωμένη παραγγελία»</h1>';
	if ( isset( $_POST['perfectpixel_resend_email'] ) && check_admin_referer( 'perfectpixel_resend_completed' ) ) {
		$email  = sanitize_email( wp_unslash( $_POST['perfectpixel_resend_email'] ) );
		$orders = $email ? wc_get_orders( array( 'billing_email' => $email, 'status' => array( 'completed' ), 'limit' => 50, 'type' => 'shop_order' ) ) : array();
		$mails  = WC()->mailer()->get_emails();
		$sent   = 0;
		if ( isset( $mails['WC_Email_Customer_Completed_Order'] ) ) {
			foreach ( $orders as $order ) {
				$mails['WC_Email_Customer_Completed_Order']->trigger( $order->get_id(), $order );
				$order->add_order_note( 'Το email «Ολοκληρωμένη παραγγελία» στάλθηκε ξανά (μαζική επαναποστολή).', false, true );
				$sent++;
			}
		}
		printf( '<div class="notice notice-%s"><p>Στάλθηκαν %d emails.</p></div>', $sent ? 'success' : 'warning', (int) $sent );
	}
	echo '<form method="post">';
	wp_nonce_field( 'perfectpixel_resend_completed' );
	echo '<p><label>Email χρέωσης πελάτη<br><input type="email" name="perfectpixel_resend_email" class="regular-text" required></label></p>';
	submit_button( 'Επαναποστολή' );
	echo '</form></div>';
}
